// Fix faces: post-processing for a finished video. The face of the person in the picture is regenerated by H3 in
// independent overlapping chunks, crossfaded and pasted back; faces that already fill the frame are left alone.
// workflows/face.api.json is written by workflows/build/openjutsu_face_build.py with Follow the mouth on;
// each request prunes it. Nodes are found by title.
import { nodeByTitle } from "./advanced.ts";
import type { ApiGraph } from "./simple.ts";

export const FACE_STYLES = ["photo", "mouth"] as const;
export type FaceStyle = (typeof FACE_STYLES)[number];

export type FaceSettings = { style: FaceStyle; seed: number; chunkSeconds: number };

export const FACE_VIDEO = "Video to fix";
export const FACE_PICTURE = "Picture 1";
export const CHUNK_SECONDS = { min: 2.5, max: 15, default: 6.5 };

// Mirrors H3FaceChunks in the swap pack, before chunks with only close-ups are dropped.
const FPS = 24;
const OVERLAP = 24;
export function faceChunkCount(durationSeconds: number, chunkSeconds: number) {
  const total = Math.floor(durationSeconds * FPS);
  const length = Math.floor((Math.floor(chunkSeconds * FPS) - 5) / 17) * 17 + 5;
  return total <= length ? 1 : Math.ceil((total - OVERLAP) / (length - OVERLAP));
}

type NodeInputs = { required?: Record<string, unknown[]>; optional?: Record<string, unknown[]> };

// face.api.json was exported on Windows, so its detectors read bbox\face_yolov8m.pt, but ComfyUI accepts only the
// spelling it lists, which is bbox/face_yolov8m.pt on Linux. The setup check already ignores the separator; this makes
// the job match it. Without the node's inputs (ComfyUI did not answer), the names stay as exported.
export function useInstalledDetectors(graph: ApiGraph, inputs: NodeInputs | undefined) {
  const unified = (name: string) => name.replaceAll("\\", "/");
  for (const node of Object.values(graph)) {
    if (node.class_type !== "H3FaceTrackCrop") continue;
    for (const input of ["detector", "fallback_detector"]) {
      const name = node.inputs[input];
      const options = (inputs?.required?.[input] ?? inputs?.optional?.[input])?.[0];
      if (typeof name !== "string" || !Array.isArray(options)) continue;
      const installed = options.find((option) => typeof option === "string" && unified(option) === unified(name));
      if (typeof installed === "string") node.inputs[input] = installed;
    }
  }
}

export function pruneFace(source: ApiGraph, settings: FaceSettings): ApiGraph {
  const graph: ApiGraph = structuredClone(source);
  const id = (title: string) => nodeByTitle(graph, title);
  const chunks = graph[id("Face Fix Chunks")].inputs;
  // Match the photo: no blurred face to follow, so H3 draws the expressions and mouth anew from the picture.
  if (settings.style === "photo") {
    delete graph[id("Blurred face (follow the mouth)")];
    delete chunks.follow_mouth;
    delete graph[id("Reference Conditioning")].inputs["ref_videos.ref_video_0"];
  }
  chunks.chunk_seconds = settings.chunkSeconds;
  graph[id("Seed")].inputs.noise_seed = settings.seed;
  return graph;
}
